<script setup>
import {state,company,api,scope,useResource} from '../lib/workspace';
const {data,loading,error}=useResource(()=>api(scope(`/storage?year_value=${state.period.slice(0,4)}`)),{files:[],persistence:''});
</script>
<template><div class="view"><header class="view-heading"><div><div class="eyebrow">SISTEMA</div><h1>Arquivos e integridade</h1><p>{{company?.name}} · exercício {{state.period.slice(0,4)}}</p></div><a v-if="state.session?.user?.role==='admin'" class="button primary" href="/api/storage/backup">Backup integral do ambiente</a></header><section class="panel"><p class="panel-body">{{data.persistence}} O backup integral contém todas as empresas, exercícios, usuários e permissões. Sua restauração é feita em pasta nova, com a origem preservada e conferência de registros, totais, vínculos e hashes.</p><p v-if="error" class="message error">{{error}}</p><p v-if="loading">Conferindo arquivos…</p><div class="table-scroll"><table><thead><tr><th>Arquivo</th><th>Categoria</th><th>SHA-256</th><th>Bytes</th><th>Integridade</th></tr></thead><tbody><tr v-for="f in data.files" :key="f.id"><td>{{f.filename}}</td><td>{{f.category}}</td><td class="mono">{{f.sha256}}</td><td>{{f.bytes}}</td><td>{{f.verified?'Conferida':'Divergente'}}</td></tr></tbody></table></div></section></div></template>
